void save_rgba_bmp(const std::filesystem::path& path, uint32_t width,
                   uint32_t height, const std::vector<uint8_t>& rgba) {
    if (width == 0 || height == 0 ||
        rgba.size() != static_cast<std::size_t>(width) * height * 4U) {
        return;
    }
    std::unique_ptr<SDL_Surface, decltype(&SDL_FreeSurface)> surface(
        SDL_CreateRGBSurfaceWithFormat(
            0, static_cast<int>(width), static_cast<int>(height), 32,
            SDL_PIXELFORMAT_RGBA32),
        SDL_FreeSurface);
    if (!surface) {
        return;
    }
    for (uint32_t y = 0; y < height; ++y) {
        std::copy_n(
            rgba.begin() + static_cast<std::ptrdiff_t>(
                               static_cast<std::size_t>(y) * width * 4U),
            static_cast<std::size_t>(width) * 4U,
            static_cast<uint8_t*>(surface->pixels) +
                static_cast<std::size_t>(y) * surface->pitch);
    }
    SDL_SaveBMP(surface.get(), path.string().c_str());
}
